<?php
// Afgeschermde voorbeeldversie van de website van Healthy Fuel (Westervoort).
// Het wachtwoord staat hier alleen als hash. Nieuw wachtwoord? Maak een nieuwe hash met
// php -r 'echo password_hash("nieuw-wachtwoord", PASSWORD_DEFAULT);' en vervang PW_HASH.
const PW_HASH = '$2y$10$6EldhvlUzjJtbqPXDIafNuApQDdt8iBF6K6Qu7FGmQVJVIeRiYoSG';

header('X-Robots-Tag: noindex, nofollow');
header('Cache-Control: private, no-store');
session_name('hfvoorbeeld');
session_set_cookie_params(['lifetime' => 0, 'path' => dirname($_SERVER['SCRIPT_NAME']) . '/', 'secure' => !empty($_SERVER['HTTPS']), 'httponly' => true, 'samesite' => 'Lax']);
session_start();

if (isset($_GET['uitloggen'])) { $_SESSION = []; session_destroy(); header('Location: ./'); exit; }

$fout = false;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $_SESSION['pogingen'] = ($_SESSION['pogingen'] ?? 0) + 1;
    if ($_SESSION['pogingen'] > 10) { usleep(2000000); }
    if (password_verify((string)($_POST['wachtwoord'] ?? ''), PW_HASH)) {
        session_regenerate_id(true);
        $_SESSION['ok'] = true; $_SESSION['pogingen'] = 0;
        header('Location: ./'); exit;
    }
    usleep(600000);
    $fout = true;
}

if (!empty($_SESSION['ok'])) {
    header('Content-Type: text/html; charset=utf-8');
    $pagina = 'site.html';
    readfile(__DIR__ . '/' . $pagina);
    exit;
}
